parameters.content:
CORREO DUPLICADO

El ID del correo ya existe en Google Sheets.

El flujo termina sin:
- clasificar el correo;
- consultar el calendario;
- generar un borrador;
- registrar nuevamente el mensaje.

parameters.jsCode:
/*
Lee todos los mensajes obtenidos por Gmail y todos los IDs registrados en Sheets.
La comparación se realiza explícitamente por ID y no depende del emparejamiento interno de n8n.
*/

const mensajes = $('Mensajes Recibidos').all().map((item) => item.json);
const filasProcesadas = $input.all().map((item) => item.json);

const idsProcesados = new Set(
  filasProcesadas
    .map((fila) => String(fila.id ?? '').trim())
    .filter(Boolean),
);

function limpiarPrefijo(valor, nombre) {
  return String(valor ?? '')
    .replace(new RegExp('^' + nombre + ':\\s*', 'i'), '')
    .trim();
}

function obtenerHeader(correo, nombre) {
  const buscado = nombre.toLowerCase();
  const headers = correo.headers;

  if (headers && !Array.isArray(headers) && typeof headers === 'object') {
    const clave = Object.keys(headers).find(
      (key) => key.toLowerCase() === buscado,
    );

    if (clave) {
      const valor = Array.isArray(headers[clave])
        ? headers[clave][0]
        : headers[clave];
      return limpiarPrefijo(valor, nombre);
    }
  }

  const headersPayload = correo.payload?.headers;
  if (Array.isArray(headersPayload)) {
    const encontrado = headersPayload.find(
      (header) => String(header.name ?? '').toLowerCase() === buscado,
    );
    if (encontrado) return String(encontrado.value ?? '').trim();
  }

  return '';
}

function datosDireccion(correo, valor, nombreHeader) {
  if (valor && typeof valor === 'object') {
    const primero = Array.isArray(valor)
      ? valor[0]
      : valor.value?.[0];

    if (primero && typeof primero === 'object') {
      return {
        email: String(primero.address ?? '').trim(),
        nombre: String(primero.name ?? '').trim(),
      };
    }
  }

  const texto = limpiarPrefijo(
    valor || obtenerHeader(correo, nombreHeader),
    nombreHeader,
  );
  const emailEncontrado = texto.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i,
  );
  const email = emailEncontrado?.[0] ?? '';
  const nombre = email
    ? texto
        .replace(email, '')
        .replace(/[<>"']/g, '')
        .replace(/^[,;\s]+|[,;\s]+$/g, '')
        .trim()
    : '';

  return { email, nombre };
}

function decodificarBase64Url(valor) {
  if (!valor) return '';
  try {
    const normalizado = String(valor)
      .replace(/-/g, '+')
      .replace(/_/g, '/');
    return Buffer.from(normalizado, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function extraerCuerpo(parte, mimePreferido) {
  if (!parte || typeof parte !== 'object') return '';

  if (
    String(parte.mimeType ?? '').toLowerCase() === mimePreferido &&
    parte.body?.data
  ) {
    return decodificarBase64Url(parte.body.data);
  }

  for (const hija of parte.parts ?? []) {
    const contenido = extraerCuerpo(hija, mimePreferido);
    if (contenido) return contenido;
  }

  return '';
}

function convertirTexto(valor) {
  if (valor === null || valor === undefined) return '';
  if (typeof valor === 'string') return valor.trim();
  if (Array.isArray(valor)) {
    return valor.map(convertirTexto).filter(Boolean).join('\n').trim();
  }
  if (typeof valor === 'object') {
    if (typeof valor.text === 'string') return valor.text.trim();
    if (typeof valor.value === 'string') return valor.value.trim();
  }
  return String(valor).trim();
}

function normalizarCorreo(correo) {
  const id = String(correo.id ?? '').trim();
  const remitente = datosDireccion(correo, correo.from, 'From');
  const destinatario = datosDireccion(correo, correo.to, 'To');

  const contenido =
    convertirTexto(correo.text) ||
    convertirTexto(correo.textPlain) ||
    extraerCuerpo(correo.payload, 'text/plain') ||
    convertirTexto(correo.html) ||
    extraerCuerpo(correo.payload, 'text/html') ||
    convertirTexto(correo.snippet);

  let fechaEmail =
    convertirTexto(correo.date) ||
    obtenerHeader(correo, 'Date');

  if (!fechaEmail && correo.internalDate) {
    const fechaCalculada = new Date(Number(correo.internalDate));
    if (!Number.isNaN(fechaCalculada.getTime())) {
      fechaEmail = fechaCalculada.toISOString();
    }
  }

  const messageId = limpiarPrefijo(
    correo.messageId || obtenerHeader(correo, 'Message-ID'),
    'Message-ID',
  );

  return {
    json: {
      id,
      thread_id: String(correo.threadId ?? '').trim(),
      message_id: messageId,
      fecha_email: fechaEmail,
      remitente_email: remitente.email,
      destinatario_email: destinatario.email,
      asunto: limpiarPrefijo(
        correo.subject || obtenerHeader(correo, 'Subject'),
        'Subject',
      ),
      contenido,
      remitente_nombre: remitente.nombre,
      es_duplicado: idsProcesados.has(id),
    },
  };
}

return mensajes.map(normalizarCorreo);

/*
El código JavaScript tiene dos objetivos:

Limpiar la respuesta de Ollama: extrae el JSON aunque el modelo agregue texto o bloques Markdown.
Unificar los datos: combina la clasificación de la IA con los datos originales del correo.

*/

const respuesta =
  $json.text ??
  $json.output ??
  $json.response ??
  $json;

let resultadoIA;

if (typeof respuesta === 'object' && respuesta !== null) {
  resultadoIA = respuesta;
} else {
  const texto = String(respuesta).trim();

  const inicio = texto.indexOf('{');
  const final = texto.lastIndexOf('}');

  if (inicio === -1 || final === -1 || final < inicio) {
    throw new Error(
      'La IA no devolvió un objeto JSON. Respuesta recibida: ' +
      texto.slice(0, 500)
    );
  }

  const jsonLimpio = texto.slice(inicio, final + 1);

  try {
    resultadoIA = JSON.parse(jsonLimpio);
  } catch (error) {
    throw new Error(
      'La IA devolvió un JSON inválido: ' +
      error.message +
      '. Respuesta: ' +
      jsonLimpio.slice(0, 500)
    );
  }
}

const correoOriginal = $('Preparar correo para IA').item.json;

return {
  json: {
    ...correoOriginal,
    ...resultadoIA
  }
};

const ZONA_HORARIA = 'America/Argentina/Buenos_Aires';

/**
 * Devuelve los datos originales indicando que la fecha
 * no pudo resolverse. No detiene todo el workflow.
 */
function devolverError(mensaje) {
  return {
    json: {
      ...$json,
      fecha_inicio: null,
      fecha_fin: null,
      fecha_calendario_resuelta: false,
      error_calendario: mensaje,
      requiere_revision_humana: true,
    },
  };
}

/**
 * Convierte textos como "mañana" o "miércoles"
 * a una versión comparable sin mayúsculas ni acentos.
 */
function normalizarTexto(valor) {
  return String(valor ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const fechaTexto = normalizarTexto($json.fecha_texto);
const horaTexto = String($json.hora ?? '').trim();
const duracion = Number($json.duracion_minutos);

/*
 * Usamos la fecha de recepción del correo como referencia.
 * Si no existe o no es válida, utilizamos la fecha actual.
 */
let referencia = DateTime.fromISO(
  String($json.fecha_email ?? ''),
  { setZone: true }
);

if (!referencia.isValid) {
  referencia = $now;
}

const hoy = referencia
  .setZone(ZONA_HORARIA)
  .startOf('day');

let fechaBase = null;

/*
 * 1. Resolver expresiones relativas.
 * Es importante evaluar "pasado mañana" antes que "mañana".
 */
if (fechaTexto.includes('pasado manana')) {
  fechaBase = hoy.plus({ days: 2 });
} else if (fechaTexto.includes('manana')) {
  fechaBase = hoy.plus({ days: 1 });
} else if (fechaTexto.includes('hoy')) {
  fechaBase = hoy;
} else {
  /*
   * 2. Resolver fechas escritas explícitamente:
   *    2026-09-05
   *    05/09/2026
   *    05-09-2026
   */
  const fechaISO = fechaTexto.match(
    /\b(\d{4})-(\d{2})-(\d{2})\b/
  );

  const fechaLocal = fechaTexto.match(
    /\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b/
  );

  if (fechaISO) {
    fechaBase = hoy.set({
      year: Number(fechaISO[1]),
      month: Number(fechaISO[2]),
      day: Number(fechaISO[3]),
    });
  } else if (fechaLocal) {
    fechaBase = hoy.set({
      year: Number(fechaLocal[3]),
      month: Number(fechaLocal[2]),
      day: Number(fechaLocal[1]),
    });
  } else {
    /*
     * 3. Resolver días de la semana.
     * Ejemplo: "el próximo viernes".
     */
    const diasSemana = {
      lunes: 1,
      martes: 2,
      miercoles: 3,
      jueves: 4,
      viernes: 5,
      sabado: 6,
      domingo: 7,
    };

    const diaEncontrado = Object.keys(diasSemana).find(
      dia => fechaTexto.includes(dia)
    );

    if (diaEncontrado) {
      const diaObjetivo = diasSemana[diaEncontrado];

      let diasHastaFecha =
        (diaObjetivo - hoy.weekday + 7) % 7;

      // Si hoy es ese día, interpretamos el próximo.
      if (diasHastaFecha === 0) {
        diasHastaFecha = 7;
      }

      fechaBase = hoy.plus({ days: diasHastaFecha });
    }
  }
}

/*
 * 4. Validaciones.
 */
if (!fechaBase || !fechaBase.isValid) {
  return devolverError(
    `No se pudo interpretar la fecha: "${$json.fecha_texto ?? ''}"`
  );
}

const horaValida = horaTexto.match(
  /^([01]?\d|2[0-3]):([0-5]\d)$/
);

if (!horaValida) {
  return devolverError(
    `La hora no es válida: "${horaTexto}". Se esperaba HH:mm`
  );
}

if (!Number.isInteger(duracion) || duracion <= 0) {
  return devolverError(
    `La duración no es válida: "${$json.duracion_minutos ?? ''}"`
  );
}

/*
 * 5. Construir el intervalo exacto.
 */
const inicio = fechaBase.set({
  hour: Number(horaValida[1]),
  minute: Number(horaValida[2]),
  second: 0,
  millisecond: 0,
});

const fin = inicio.plus({
  minutes: duracion,
});

/*
 * 6. Entregar los datos originales junto con
 * las fechas calculadas.
 */
return {
  json: {
    ...$json,
    fecha_inicio: inicio.toISO({
      suppressMilliseconds: true,
    }),
    fecha_fin: fin.toISO({
      suppressMilliseconds: true,
    }),
    fecha_calendario_resuelta: true,
    error_calendario: null,
  },
};

// Recuperar todos los datos anteriores del correo.
const datosCorreo =
  $('Resolver fecha calendario').item.json;

// Resultado entregado por Google Calendar.
const valorDisponibilidad = $json.available;

// Aceptamos tanto booleanos como textos.
const resultadoValido =
  valorDisponibilidad === true ||
  valorDisponibilidad === false ||
  valorDisponibilidad === 'true' ||
  valorDisponibilidad === 'false';

if (!resultadoValido) {
  return {
    json: {
      ...datosCorreo,
      disponibilidad_consultada: false,
      horario_disponible: null,
      error_calendario:
        'Google Calendar no devolvió un valor de disponibilidad válido',
      requiere_revision_humana: true,
    },
  };
}

const horarioDisponible =
  valorDisponibilidad === true ||
  valorDisponibilidad === 'true';

return {
  json: {
    ...datosCorreo,
    disponibilidad_consultada: true,
    horario_disponible: horarioDisponible,
    error_calendario: null,
  },
};

// Recuperamos el correo y el resultado del calendario.
const datosCorreo =
  $('Unificar disponibilidad con correo').item.json;

// Recuperamos el HTML generado por Ollama.
let cuerpoHtml = String($json.text ?? '').trim();

// Eliminamos bloques Markdown si Ollama los agregara accidentalmente.
cuerpoHtml = cuerpoHtml
  .replace(/^```(?:html)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// Validaciones importantes.
if (!cuerpoHtml) {
  throw new Error(
    'Ollama no generó contenido para el borrador'
  );
}

const destinatario =
  String(datosCorreo.remitente_email ?? '').trim();

if (!destinatario) {
  throw new Error(
    'No se encontró el correo del remitente'
  );
}

const threadId =
  String(datosCorreo.thread_id ?? '').trim();

if (!threadId) {
  throw new Error(
    'No se encontró el thread_id del correo'
  );
}

// Evitamos generar asuntos como "Re: Re: ...".
const asuntoOriginal =
  String(datosCorreo.asunto ?? '').trim();

const asuntoBorrador =
  /^re\s*:/i.test(asuntoOriginal)
    ? asuntoOriginal
    : `Re: ${asuntoOriginal}`;

return {
  json: {
    ...datosCorreo,

    // Campos preparados para Gmail.
    destinatario_borrador: destinatario,
    asunto_borrador: asuntoBorrador,
    cuerpo_html: cuerpoHtml,
    thread_id: threadId,

    // Estado interno del procesamiento.
    respuesta_preparada: true,
    borrador_generado: false,
    evento_creado: false,
  },
};

// Recuperar los datos preparados antes de llamar a Gmail.
const datosCorreo =
  $('Preparar borrador Gmail').item.json;

// Intentar recuperar los identificadores devueltos por Gmail.
const draftId =
  $json.id ??
  $json.draftId ??
  null;

const mensajeBorradorId =
  $json.message?.id ??
  $json.messageId ??
  null;

return {
  json: {
    ...datosCorreo,

    // Información devuelta por Gmail.
    draft_id: draftId,
    mensaje_borrador_id: mensajeBorradorId,

    // Estados del procesamiento.
    respuesta_generada: true,
    borrador_generado: true,
    fecha_procesamiento: $now
      .setZone('America/Argentina/Buenos_Aires')
      .toISO(),
  },
};
